import{c as r,Q as o,j as d,m as n}from"./chunks/framework.rWdQudnF.js";const p=JSON.parse('{"title":"架构师-备考 综合知识-数据库-数据仓库","description":"","frontmatter":{"title":"架构师-备考 综合知识-数据库-数据仓库"},"headers":[],"relativePath":"综合知识/数据库/数据仓库.md","filePath":"综合知识/数据库/数据仓库.md","lastUpdated":null}'),s={name:"综合知识/数据库/数据仓库.md"};function a(e,t,l,g,h,i){return o(),d("div",null,[...t[0]||(t[0]=[n('<h3 id="数据仓库" tabindex="-1">数据仓库 <a class="header-anchor" href="#数据仓库" aria-label="Permalink to &quot;数据仓库&quot;">​</a></h3><blockquote><p><strong>数据仓库</strong>是一个**面向主题的、集成的、相对稳定的（非易失的）、反映历史变化（随时间变化）**的数据集合，用于支持管理决策。</p></blockquote><table tabindex="0"><thead><tr><th>特征</th><th>说明</th></tr></thead><tbody><tr><td><strong>面向主题</strong></td><td>按照一定的主题域进行组织</td></tr><tr><td><strong>集成的</strong></td><td>对原有分散数据库数据抽取、清理后加工、汇总、整理，消除不一致性</td></tr><tr><td><strong>相对稳定的</strong></td><td>主要供企业决策分析，涉及操作主要是查询，修改和删除很少</td></tr><tr><td><strong>反映历史变化</strong></td><td>包含历史信息，可对企业发展历程和未来趋势做定量分析和预测</td></tr></tbody></table><p><strong>数据仓库四层结构：</strong></p><ol><li><strong>数据源</strong>：整个系统的数据源泉</li><li><strong>数据的存储与管理</strong>：整个数据仓库系统的<strong>核心</strong></li><li><strong>OLAP 服务器</strong>：对分析需要的数据进行有效集成，按多维模型组织，支持多角度、多层次分析</li><li><strong>前端工具</strong>：报表工具、查询工具、数据分析工具、数据挖掘工具等</li></ol><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/Pasted%20image%2020230830234443.png" alt="数据仓库结构"></p><hr><h3 id="商业智能-bi" tabindex="-1">商业智能（BI） <a class="header-anchor" href="#商业智能-bi" aria-label="Permalink to &quot;商业智能（BI）&quot;">​</a></h3><p>BI 系统的四个主要阶段：</p><ol><li><strong>数据预处理（ETL）</strong>：数据的抽取（Extraction）、转换（Transformation）和加载（Load）</li><li><strong>建立数据仓库</strong>：处理海量数据的基础</li><li><strong>数据分析</strong>：核心智能环节，采用 OLAP 和数据挖掘两大技术 <ul><li><strong>OLAP（联机分析处理）</strong>：数据汇总/聚集，支持<strong>切片、切块、下钻、上卷和旋转</strong>等操作，用户可对海量数据进行多维分析</li><li><strong>数据挖掘</strong>：挖掘数据背后隐藏的知识，通过关联分析、聚类和分类等方法建立分析模型</li></ul></li><li><strong>数据展现</strong>：保障系统分析结果的可视化</li></ol><hr><h3 id="数据挖掘" tabindex="-1">数据挖掘 <a class="header-anchor" href="#数据挖掘" aria-label="Permalink to &quot;数据挖掘&quot;">​</a></h3><blockquote><p>数据挖掘是从数据库的大量数据中揭示出隐含的、先前未知的并有潜在价值的信息的非平凡过程。</p></blockquote><p><strong>主要任务</strong>：关联分析、聚类分析、分类分析、异常分析、特异群组分析和演变分析等。</p><hr><h3 id="反规范化技术" tabindex="-1">反规范化技术 <a class="header-anchor" href="#反规范化技术" aria-label="Permalink to &quot;反规范化技术&quot;">​</a></h3><blockquote><p><strong>定义</strong>：规范化设计后，数据库设计者希望<strong>牺牲部分规范化来提高性能</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>益处</th><th>问题</th></tr></thead><tbody><tr><td>降低连接操作的需求</td><td>数据的重复存储，浪费磁盘空间</td></tr><tr><td>降低外码和索引的数目</td><td>可能出现数据完整性问题</td></tr><tr><td>可能减少表的数目</td><td>增加数据维护的复杂性，降低修改速度</td></tr><tr><td>提高查询效率</td><td></td></tr></tbody></table><p><strong>具体方法：</strong></p><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><strong>增加冗余列</strong></td><td>在多个表中保留相同的列，减少或避免查询时的连接操作</td></tr><tr><td><strong>增加派生列</strong></td><td>增加可由本表或其它表中数据计算生成的列，减少连接和计算</td></tr><tr><td><strong>重新组表</strong></td><td>将经常一起查询的两个表重新组成一个表来减少连接</td></tr><tr><td><strong>水平分割表</strong></td><td>根据列值，把数据放到多个独立的表中（适用于数据规模大、数据相对独立）</td></tr><tr><td><strong>垂直分割表</strong></td><td>将主键与部分列放一个表，主键与其它列放另一个表，减少查询 I/O</td></tr></tbody></table><hr><h3 id="大数据" tabindex="-1">大数据 <a class="header-anchor" href="#大数据" aria-label="Permalink to &quot;大数据&quot;">​</a></h3><p><strong>四大特点</strong>：大量化（Volume）、多样化（Variety）、价值密度低（Value）、快速化（Velocity）。</p><p><strong>传统数据 vs 大数据：</strong></p><table tabindex="0"><thead><tr><th>比较维度</th><th>传统数据</th><th>大数据</th></tr></thead><tbody><tr><td>数据量</td><td>GB 或 TB 级</td><td>PB 级或以上</td></tr><tr><td>数据分析需求</td><td>现有数据的分析与检测</td><td>深度分析（关联分析、回归分析）</td></tr><tr><td>硬件平台</td><td>高端服务器</td><td>集群平台</td></tr></tbody></table><p><strong>大数据处理系统特征</strong>：高度可扩展性、高性能、高度容错、支持异构环境、较短的分析延迟、易用且开放的接口、较低成本、向下兼容性。</p><hr><h3 id="数据库安全-备份与恢复" tabindex="-1">数据库安全（备份与恢复） <a class="header-anchor" href="#数据库安全-备份与恢复" aria-label="Permalink to &quot;数据库安全（备份与恢复）&quot;">​</a></h3><p><strong>备份类型：</strong></p><table tabindex="0"><thead><tr><th>分类方式</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>按转储方式</td><td><strong>静态转储</strong>（冷备份）</td><td>转储期间不允许任何存取、修改操作。优点：快速、易归档。缺点：只能恢复到某一时间点</td></tr><tr><td></td><td><strong>动态转储</strong>（热备份）</td><td>转储期间允许存取、修改操作，转储和用户事务可并发执行。优点：可在表空间级备份，可达秒级恢复。缺点：若失败结果几乎全部无效</td></tr><tr><td>按备份内容</td><td><strong>完全备份</strong></td><td>备份所有数据</td></tr><tr><td></td><td><strong>差量备份</strong></td><td>仅备份上一次完全备份之后变化的数据</td></tr><tr><td></td><td><strong>增量备份</strong></td><td>备份上一次备份之后变化的数据</td></tr></tbody></table><p><strong>日志文件：</strong></p><blockquote><p>在事务处理过程中，DBMS 把<strong>事务开始、事务结束</strong>以及<strong>对数据库的插入、删除和修改</strong>的每一次操作写入日志文件。一旦发生故障，DBMS 的恢复子系统利用日志文件撤销事务对数据库的改变，回退到事务的初始状态。</p></blockquote><blockquote><p><strong>关键题点</strong>：日志文件记录的是<strong>操作内容</strong>，数据文件存放的是<strong>实际数据</strong>。恢复时依据日志文件可知有哪些操作，依据数据文件可知操作的数据是什么。</p></blockquote>',33)])])}const c=r(s,[["render",a]]);export{p as __pageData,c as default};
